// ─── REAL SQLite DATABASE ENGINE (sql.js WebAssembly) ───
// This is a REAL database running SQLite in the browser via WebAssembly.
// All tables, queries, inserts, and selects are real SQL operations.
// Data persists in localStorage as a serialized database blob.

import initSqlJs from 'sql.js';

const DB_STORAGE_KEY = 'bankingQA_sqliteDB';
let db = null;
let SQL = null;

// Initialize the database
export async function initDatabase() {
  if (db) return db;
  SQL = await initSqlJs({
    locateFile: file => `${process.env.PUBLIC_URL}/${file}`
  });

  // Try to load existing database from localStorage
  const savedDb = localStorage.getItem(DB_STORAGE_KEY);
  if (savedDb) {
    try {
      const buf = Uint8Array.from(atob(savedDb), c => c.charCodeAt(0));
      db = new SQL.Database(buf);
    } catch {
      db = new SQL.Database();
      createTables();
      seedData();
    }
  } else {
    db = new SQL.Database();
    createTables();
    seedData();
  }
  return db;
}

// Save database to localStorage
function saveDb() {
  if (!db) return;
  const data = db.export();
  const base64 = btoa(String.fromCharCode(...data));
  try {
    localStorage.setItem(DB_STORAGE_KEY, base64);
  } catch (e) {
    // localStorage full — trim old logs
    db.run("DELETE FROM test_logs WHERE id NOT IN (SELECT id FROM test_logs ORDER BY timestamp DESC LIMIT 500)");
    const data2 = db.export();
    const base642 = btoa(String.fromCharCode(...data2));
    localStorage.setItem(DB_STORAGE_KEY, base642);
  }
}

// ─── CREATE ALL TABLES ───
function createTables() {
  db.run(`
    CREATE TABLE IF NOT EXISTS pages (
      page_key TEXT PRIMARY KEY,
      label TEXT NOT NULL,
      section TEXT NOT NULL,
      icon TEXT,
      scenario_count INTEGER DEFAULT 0,
      has_test_runner INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now'))
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS test_scenarios (
      id TEXT PRIMARY KEY,
      page_key TEXT NOT NULL,
      title TEXT NOT NULL,
      priority TEXT DEFAULT 'P1',
      type TEXT DEFAULT 'Functional',
      is_manual INTEGER DEFAULT 0,
      category TEXT,
      component TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (page_key) REFERENCES pages(page_key)
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS test_runs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      scenario_id TEXT NOT NULL,
      page_key TEXT NOT NULL,
      result TEXT NOT NULL,
      type TEXT NOT NULL,
      duration_ms INTEGER,
      test_data TEXT,
      notes TEXT,
      executed_by TEXT DEFAULT 'system',
      run_date TEXT,
      run_time TEXT,
      timestamp TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (scenario_id) REFERENCES test_scenarios(id)
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS bugs (
      id TEXT PRIMARY KEY,
      scenario_id TEXT,
      page_key TEXT NOT NULL,
      title TEXT NOT NULL,
      description TEXT,
      severity TEXT NOT NULL,
      priority TEXT DEFAULT 'P1',
      status TEXT DEFAULT 'Open',
      component TEXT,
      category TEXT,
      found_by TEXT DEFAULT 'Automation',
      assigned_to TEXT,
      steps_to_reproduce TEXT,
      expected_result TEXT,
      actual_result TEXT,
      environment TEXT DEFAULT 'QA',
      fix_version TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      resolved_at TEXT,
      FOREIGN KEY (scenario_id) REFERENCES test_scenarios(id)
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS test_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      level TEXT NOT NULL,
      source TEXT NOT NULL,
      page_key TEXT,
      scenario_id TEXT,
      message TEXT NOT NULL,
      details TEXT,
      user_action TEXT,
      ip_address TEXT DEFAULT '127.0.0.1',
      browser TEXT,
      timestamp TEXT DEFAULT (datetime('now'))
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS scheduled_jobs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      scenario_id TEXT NOT NULL,
      page_key TEXT NOT NULL,
      interval_type TEXT DEFAULT 'every5min',
      interval_ms INTEGER DEFAULT 300000,
      status TEXT DEFAULT 'active',
      next_run TEXT,
      last_run TEXT,
      run_count INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (scenario_id) REFERENCES test_scenarios(id)
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS test_reports (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      page_key TEXT NOT NULL,
      report_type TEXT DEFAULT 'execution',
      total_scenarios INTEGER,
      tested INTEGER,
      passed INTEGER,
      failed INTEGER,
      blocked INTEGER,
      skipped INTEGER,
      pass_rate REAL,
      bugs_found INTEGER DEFAULT 0,
      executed_by TEXT DEFAULT 'system',
      report_json TEXT,
      generated_at TEXT DEFAULT (datetime('now'))
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS customers (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      customer_id TEXT UNIQUE NOT NULL,
      name TEXT NOT NULL,
      pan TEXT,
      aadhaar TEXT,
      dob TEXT,
      email TEXT,
      phone TEXT,
      address TEXT,
      city TEXT,
      state TEXT,
      pincode TEXT,
      kyc_status TEXT DEFAULT 'Pending',
      created_at TEXT DEFAULT (datetime('now'))
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS accounts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      account_no TEXT UNIQUE NOT NULL,
      customer_id TEXT NOT NULL,
      type TEXT NOT NULL,
      balance REAL DEFAULT 0,
      currency TEXT DEFAULT 'INR',
      status TEXT DEFAULT 'Active',
      branch_code TEXT,
      ifsc TEXT,
      opened_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS transactions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      txn_ref TEXT UNIQUE NOT NULL,
      from_account TEXT,
      to_account TEXT,
      amount REAL NOT NULL,
      type TEXT NOT NULL,
      mode TEXT,
      status TEXT DEFAULT 'Success',
      description TEXT,
      timestamp TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (from_account) REFERENCES accounts(account_no)
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS loans (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      loan_id TEXT UNIQUE NOT NULL,
      customer_id TEXT NOT NULL,
      type TEXT NOT NULL,
      amount REAL NOT NULL,
      tenure_months INTEGER,
      interest_rate REAL,
      emi REAL,
      status TEXT DEFAULT 'Active',
      disbursed_at TEXT,
      FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS audit_log (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      entity_type TEXT NOT NULL,
      entity_id TEXT NOT NULL,
      action TEXT NOT NULL,
      old_value TEXT,
      new_value TEXT,
      performed_by TEXT DEFAULT 'system',
      ip_address TEXT DEFAULT '127.0.0.1',
      timestamp TEXT DEFAULT (datetime('now'))
    )
  `);

  // Create indexes
  db.run("CREATE INDEX IF NOT EXISTS idx_test_runs_scenario ON test_runs(scenario_id)");
  db.run("CREATE INDEX IF NOT EXISTS idx_test_runs_page ON test_runs(page_key)");
  db.run("CREATE INDEX IF NOT EXISTS idx_test_runs_result ON test_runs(result)");
  db.run("CREATE INDEX IF NOT EXISTS idx_test_runs_timestamp ON test_runs(timestamp)");
  db.run("CREATE INDEX IF NOT EXISTS idx_bugs_page ON bugs(page_key)");
  db.run("CREATE INDEX IF NOT EXISTS idx_bugs_severity ON bugs(severity)");
  db.run("CREATE INDEX IF NOT EXISTS idx_bugs_status ON bugs(status)");
  db.run("CREATE INDEX IF NOT EXISTS idx_bugs_component ON bugs(component)");
  db.run("CREATE INDEX IF NOT EXISTS idx_bugs_category ON bugs(category)");
  db.run("CREATE INDEX IF NOT EXISTS idx_test_logs_level ON test_logs(level)");
  db.run("CREATE INDEX IF NOT EXISTS idx_test_logs_page ON test_logs(page_key)");
  db.run("CREATE INDEX IF NOT EXISTS idx_test_logs_timestamp ON test_logs(timestamp)");
  db.run("CREATE INDEX IF NOT EXISTS idx_transactions_from ON transactions(from_account)");
  db.run("CREATE INDEX IF NOT EXISTS idx_audit_timestamp ON audit_log(timestamp)");

  saveDb();
}

