// ─── QUERY HELPERS ───
export function runQuery(sql, params = []) {
  if (!db) return [];
  try {
    const stmt = db.prepare(sql);
    if (params.length) stmt.bind(params);
    const results = [];
    while (stmt.step()) results.push(stmt.getAsObject());
    stmt.free();
    return results;
  } catch (e) {
    addLog('ERROR', 'Query', `SQL Error: ${e.message}`, sql);
    return [];
  }
}

export function runExec(sql, params = []) {
  if (!db) return;
  try {
    db.run(sql, params);
    saveDb();
  } catch (e) {
    addLog('ERROR', 'Exec', `SQL Error: ${e.message}`, sql);
  }
}

// ─── LOG FUNCTIONS ───
export function addLog(level, source, message, details = '', pageKey = '', scenarioId = '') {
  if (!db) return;
  db.run(
    "INSERT INTO test_logs (level,source,page_key,scenario_id,message,details,browser,timestamp) VALUES (?,?,?,?,?,?,?,datetime('now'))",
    [level, source, pageKey, scenarioId, message, details, navigator.userAgent || 'unknown']
  );
  saveDb();
}

export function getLogs(limit = 100, level = '') {
  let sql = "SELECT * FROM test_logs";
  const params = [];
  if (level) { sql += " WHERE level = ?"; params.push(level); }
  sql += " ORDER BY timestamp DESC LIMIT ?";
  params.push(limit);
  return runQuery(sql, params);
}

// ─── TEST RUN FUNCTIONS ───
export function addTestRun(scenarioId, pageKey, result, type, durationMs, testData = '', notes = '') {
  const now = new Date();
  runExec(
    "INSERT INTO test_runs (scenario_id,page_key,result,type,duration_ms,test_data,notes,run_date,run_time,timestamp) VALUES (?,?,?,?,?,?,?,?,?,?)",
    [scenarioId, pageKey, result, type, durationMs, testData, notes, now.toLocaleDateString(), now.toLocaleTimeString(), now.toISOString()]
  );
  addLog('INFO', 'TestRun', `${type} test ${result}: ${scenarioId}`, `Duration: ${durationMs}ms, Data: ${testData}`, pageKey, scenarioId);
  // Add audit entry
  runExec("INSERT INTO audit_log (entity_type,entity_id,action,new_value,performed_by) VALUES ('test_run',?,?,?,?)",
    ['test_run', scenarioId, result, `${type} | ${durationMs}ms`, 'system']);
}

export function getTestRuns(pageKey, limit = 50) {
  return runQuery("SELECT * FROM test_runs WHERE page_key = ? ORDER BY timestamp DESC LIMIT ?", [pageKey, limit]);
}

export function getTestRunsByScenario(scenarioId, limit = 20) {
  return runQuery("SELECT * FROM test_runs WHERE scenario_id = ? ORDER BY timestamp DESC LIMIT ?", [scenarioId, limit]);
}

// ─── BUG FUNCTIONS ───
export function addBug(id, pageKey, title, description, severity, component, category, scenarioId = '') {
  runExec(
    "INSERT OR IGNORE INTO bugs (id,page_key,title,description,severity,component,category,scenario_id) VALUES (?,?,?,?,?,?,?,?)",
    [id, pageKey, title, description, severity, component, category, scenarioId]
  );
  addLog('WARN', 'BugTracker', `New bug: ${id} - ${title} [${severity}]`, '', pageKey, scenarioId);
}

export function getBugs(pageKey = '', status = '') {
  let sql = "SELECT * FROM bugs";
  const conditions = [];
  const params = [];
  if (pageKey) { conditions.push("page_key = ?"); params.push(pageKey); }
  if (status) { conditions.push("status = ?"); params.push(status); }
  if (conditions.length) sql += " WHERE " + conditions.join(" AND ");
  sql += " ORDER BY CASE severity WHEN 'Critical' THEN 1 WHEN 'Major' THEN 2 WHEN 'Minor' THEN 3 ELSE 4 END, created_at DESC";
  return runQuery(sql, params);
}

export function getBugsByComponent(pageKey) {
  return runQuery(
    "SELECT component, category, COUNT(*) as count, SUM(CASE WHEN status='Fixed' THEN 1 ELSE 0 END) as fixed, SUM(CASE WHEN status='Open' THEN 1 ELSE 0 END) as open FROM bugs WHERE page_key = ? GROUP BY component, category ORDER BY count DESC",
    [pageKey]
  );
}

export function updateBugStatus(bugId, status) {
  const resolved = status === 'Fixed' ? ",resolved_at=datetime('now')" : '';
  runExec(`UPDATE bugs SET status=?, updated_at=datetime('now')${resolved} WHERE id=?`, [status, bugId]);
  addLog('INFO', 'BugTracker', `Bug ${bugId} status changed to ${status}`);
}

// ─── REPORT FUNCTIONS ───
export function generateReport(pageKey) {
  const runs = runQuery("SELECT result, COUNT(*) as cnt FROM test_runs WHERE page_key = ? GROUP BY result", [pageKey]);
  const total = runQuery("SELECT scenario_count FROM pages WHERE page_key = ?", [pageKey]);
  const bugCount = runQuery("SELECT COUNT(*) as cnt FROM bugs WHERE page_key = ?", [pageKey]);
  const summary = { total: total[0]?.scenario_count || 0, tested: 0, passed: 0, failed: 0, blocked: 0, skipped: 0 };
  runs.forEach(r => {
    summary.tested += r.cnt;
    if (r.result === 'Pass') summary.passed = r.cnt;
    if (r.result === 'Fail') summary.failed = r.cnt;
    if (r.result === 'Blocked') summary.blocked = r.cnt;
    if (r.result === 'Skipped') summary.skipped = r.cnt;
  });
  summary.passRate = summary.tested > 0 ? Math.round((summary.passed / summary.tested) * 100) : 0;
  summary.bugsFound = bugCount[0]?.cnt || 0;

  runExec(
    "INSERT INTO test_reports (page_key,total_scenarios,tested,passed,failed,blocked,skipped,pass_rate,bugs_found,report_json) VALUES (?,?,?,?,?,?,?,?,?,?)",
    [pageKey, summary.total, summary.tested, summary.passed, summary.failed, summary.blocked, summary.skipped, summary.passRate, summary.bugsFound, JSON.stringify(summary)]
  );
  addLog('INFO', 'Reports', `Report generated for ${pageKey}: ${summary.passRate}% pass rate`, '', pageKey);
  return summary;
}

export function getReports(pageKey = '') {
  if (pageKey) return runQuery("SELECT * FROM test_reports WHERE page_key = ? ORDER BY generated_at DESC", [pageKey]);
  return runQuery("SELECT * FROM test_reports ORDER BY generated_at DESC LIMIT 50");
}

// ─── DASHBOARD STATS ───
export function getDashboardStats() {
  const totalPages = runQuery("SELECT COUNT(*) as cnt FROM pages")[0]?.cnt || 0;
  const totalScenarios = runQuery("SELECT SUM(scenario_count) as cnt FROM pages")[0]?.cnt || 0;
  const totalRuns = runQuery("SELECT COUNT(*) as cnt FROM test_runs")[0]?.cnt || 0;
  const totalBugs = runQuery("SELECT COUNT(*) as cnt FROM bugs")[0]?.cnt || 0;
  const openBugs = runQuery("SELECT COUNT(*) as cnt FROM bugs WHERE status='Open'")[0]?.cnt || 0;
  const criticalBugs = runQuery("SELECT COUNT(*) as cnt FROM bugs WHERE severity='Critical'")[0]?.cnt || 0;
  const passRate = runQuery("SELECT ROUND(AVG(CASE WHEN result='Pass' THEN 100.0 ELSE 0 END),1) as rate FROM test_runs")[0]?.rate || 0;
  const totalCustomers = runQuery("SELECT COUNT(*) as cnt FROM customers")[0]?.cnt || 0;
  const totalAccounts = runQuery("SELECT COUNT(*) as cnt FROM accounts")[0]?.cnt || 0;
  const totalTransactions = runQuery("SELECT COUNT(*) as cnt FROM transactions")[0]?.cnt || 0;
  const totalLoans = runQuery("SELECT COUNT(*) as cnt FROM loans")[0]?.cnt || 0;
  return { totalPages, totalScenarios, totalRuns, totalBugs, openBugs, criticalBugs, passRate, totalCustomers, totalAccounts, totalTransactions, totalLoans };
}

// ─── TABLE INFO ───
export function getTableInfo() {
  const tables = runQuery("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name");
  return tables.map(t => {
    const info = runQuery(`PRAGMA table_info(${t.name})`);
    const count = runQuery(`SELECT COUNT(*) as cnt FROM ${t.name}`)[0]?.cnt || 0;
    return { name: t.name, columns: info.length, rows: count, columnDetails: info };
  });
}

export function getTableData(tableName, limit = 50, offset = 0) {
  return runQuery(`SELECT * FROM ${tableName} LIMIT ? OFFSET ?`, [limit, offset]);
}

// ─── RESET DATABASE ───
export function resetDatabase() {
  localStorage.removeItem(DB_STORAGE_KEY);
  db = null;
  return initDatabase();
}
