const suiteBadge = (s) => {
  const m = {Smoke:'#e65100',Sanity:'#1565c0',Regression:'#6a1b9a',Full:'#2e7d32',UAT:'#c62828',Performance:'#00695c',Security:'#b71c1c'};
  return <span style={{background:m[s]||'#adb5bd',color:'#fff',padding:'1px 6px',borderRadius:4,fontSize:8,fontWeight:700}}>{s}</span>;
};
const HighlightText = ({text,query}) => {
  if(!query||!text||query.length<2) return <>{text}</>;
  const idx=text.toLowerCase().indexOf(query.toLowerCase());
  if(idx===-1) return <>{text}</>;
  return <>{text.substring(0,idx)}<mark style={{background:'#fff176',padding:0,borderRadius:2}}>{text.substring(idx,idx+query.length)}</mark>{text.substring(idx+query.length)}</>;
};
