// ================================================================
//  COMPONENT
// ================================================================

function TestMethodologies() {
  const [activeTab, setActiveTab] = useState('integration');
  const [expandedCards, setExpandedCards] = useState({});

  const tabData = TAB_DATA[activeTab];
  const scenarios = tabData.scenarios;

  // Severity counts for stats bar
  const counts = { total: scenarios.length, Critical: 0, High: 0, Medium: 0, Low: 0 };
  scenarios.forEach((sc) => { counts[sc.severity] = (counts[sc.severity] || 0) + 1; });

  const toggleCard = (id) => {
    setExpandedCards((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const handleTabChange = (tabId) => {
    setActiveTab(tabId);
    setExpandedCards({});
  };

  return (
    <div style={S.page}>
      {/* Header */}
      <div style={S.header}>
        <h1 style={S.title}>Test Methodologies</h1>
        <p style={S.subtitle}>
          Comprehensive banking QA test scenarios across 5 core testing methodologies
        </p>
      </div>

      {/* Tab Bar */}
      <div style={S.tabs}>
        {TABS.map((tab) => (
          <button
            key={tab.id}
            style={S.tab(activeTab === tab.id)}
            onClick={() => handleTabChange(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Description */}
      <div style={S.description}>{tabData.description}</div>

      {/* Stats Bar */}
      <div style={S.statsRow}>
        <div style={S.statBox('#0d6efd')}>
          <div style={S.statVal('#0d6efd')}>{counts.total}</div>
          <div style={S.statLabel}>Total</div>
        </div>
        <div style={S.statBox(C.severityCritical)}>
          <div style={S.statVal(C.severityCritical)}>{counts.Critical}</div>
          <div style={S.statLabel}>Critical</div>
        </div>
        <div style={S.statBox(C.severityHigh)}>
          <div style={S.statVal(C.severityHigh)}>{counts.High}</div>
          <div style={S.statLabel}>High</div>
        </div>
        <div style={S.statBox(C.severityMedium)}>
          <div style={S.statVal(C.severityMedium)}>{counts.Medium}</div>
          <div style={S.statLabel}>Medium</div>
        </div>
        <div style={S.statBox(C.severityLow)}>
          <div style={S.statVal(C.severityLow)}>{counts.Low}</div>
          <div style={S.statLabel}>Low</div>
        </div>
      </div>

      {/* Card List */}
      <div style={S.cardList}>
        {scenarios.map((sc) => {
          const expanded = !!expandedCards[sc.id];
          return (
            <div key={sc.id} style={S.card(expanded)}>
              {/* Card Header */}
              <div style={S.cardHeader} onClick={() => toggleCard(sc.id)}>
                <div style={S.cardHeaderLeft}>
                  <span style={S.idBadge}>{sc.id}</span>
                  <span style={S.cardTitle}>{sc.title}</span>
                </div>
                <span style={S.severityBadge(sc.severity)}>{sc.severity}</span>
                <span style={S.categoryTag}>{sc.category}</span>
                <span style={S.expandArrow(expanded)}>&#9660;</span>
              </div>

              {/* Card Body (expanded) */}
              {expanded && (
                <div style={S.cardBody}>
                  <div style={S.descText}>{sc.description}</div>

                  <div style={S.stepsTitle}>Test Steps</div>
                  {sc.steps.map((step, idx) => (
                    <div key={idx} style={S.stepItem}>
                      <span style={S.stepNumber}>{idx + 1}</span>
                      <span>{step}</span>
                    </div>
                  ))}

                  <div style={S.expectedBox}>
                    <div style={S.expectedTitle}>Expected Result</div>
                    <div style={S.expectedText}>{sc.expectedResult}</div>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default TestMethodologies;
