// ─── API SERVICE LAYER ───────────────────────────────────────────────────────
// Real callable API service backing all 176 endpoints across 26 pages.
// Each handler queries the real SQLite database via db.js helpers.
// ─────────────────────────────────────────────────────────────────────────────

import {
  initDatabase, runQuery, runExec, addLog,
  addTestRun, getTestRuns, getBugs, addBug,
  getBugsByComponent, updateBugStatus, generateReport,
  getReports, getDashboardStats, getTableInfo, getTableData, getLogs
} from '../database/db.js';

// ─── UTILITY HELPERS ─────────────────────────────────────────────────────────

function ts() { return new Date().toISOString(); }
function uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 7).toUpperCase(); }
function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function randFloat(min, max, dp = 2) { return parseFloat((Math.random() * (max - min) + min).toFixed(dp)); }
function randItem(arr) { return arr[Math.floor(Math.random() * arr.length)]; }

function ok(data, extra = {}) {
  return { status: 200, data, timestamp: ts(), ...extra };
}
function errResp(msg, code = 500) {
  return { status: code, data: { detail: msg, error_code: code === 404 ? 'NOT_FOUND' : 'INTERNAL_ERROR' }, timestamp: ts() };
}
function logApi(endpoint, method, pageKey) {
  addLog('INFO', 'API', method + ' ' + endpoint, '', pageKey || 'api');
}

// ─── SECTION 1: BANKING CORE (banking-usecases) — 10 APIs ───────────────────

/**
 * Banking Use Cases API handlers.
 * Queries customers, accounts, transactions, loans, audit_log tables.
 */
const BankingApi = {

  getCustomers() {
    const t0 = Date.now();
    logApi('/api/banking/customers', 'GET', 'banking-usecases');
    const customers = runQuery('SELECT * FROM customers ORDER BY name LIMIT 100');
    return ok({ customers, total: customers.length }, { latency: (Date.now() - t0) + 'ms' });
  },

  getAccounts(customerId) {
    const t0 = Date.now();
    logApi('/api/banking/accounts/' + customerId, 'GET', 'banking-usecases');
    const customer = runQuery('SELECT * FROM customers WHERE customer_id = ?', [customerId]);
    if (!customer.length) return errResp('Customer ' + customerId + ' not found', 404);
    const accounts = runQuery('SELECT * FROM accounts WHERE customer_id = ?', [customerId]);
    return ok({ customerId, customer: customer[0], accounts, totalAccounts: accounts.length }, { latency: (Date.now() - t0) + 'ms' });
  },

  postTransfer(params) {
    const t0 = Date.now();
    const { fromAccount, toAccount, amount, mode = 'NEFT', description = 'Fund Transfer' } = params || {};
    logApi('/api/banking/transfer', 'POST', 'banking-usecases');
    if (!fromAccount || !toAccount || !amount) return errResp('fromAccount, toAccount, amount are required', 400);
    if (amount <= 0) return errResp('Amount must be positive', 400);
    const src = runQuery('SELECT * FROM accounts WHERE account_no = ?', [fromAccount]);
    const dst = runQuery('SELECT * FROM accounts WHERE account_no = ?', [toAccount]);
    if (!src.length) return errResp('Source account ' + fromAccount + ' not found', 404);
    if (!dst.length) return errResp('Destination account ' + toAccount + ' not found', 404);
    if (src[0].balance < amount) return errResp('Insufficient balance', 400);
    const ref = 'TXN' + uid();
    runExec('UPDATE accounts SET balance = balance - ? WHERE account_no = ?', [amount, fromAccount]);
    runExec('UPDATE accounts SET balance = balance + ? WHERE account_no = ?', [amount, toAccount]);
    runExec("INSERT INTO transactions (txn_ref,from_account,to_account,amount,type,mode,status,description,timestamp) VALUES (?,?,?,?,'Transfer',?,'Success',?,datetime('now'))",
      [ref, fromAccount, toAccount, amount, mode, description]);
    runExec("INSERT INTO audit_log (entity_type,entity_id,action,new_value,performed_by) VALUES ('transaction',?,'TRANSFER',?,?)",
      [ref, JSON.stringify({ fromAccount, toAccount, amount, mode }), 'api']);
    return ok({ txnRef: ref, fromAccount, toAccount, amount, mode, status: 'Success', message: 'Transfer completed successfully' }, { latency: (Date.now() - t0) + 'ms' });
  },

  getTransactions(accountNo) {
    const t0 = Date.now();
    logApi('/api/banking/transactions/' + accountNo, 'GET', 'banking-usecases');
    const account = runQuery('SELECT * FROM accounts WHERE account_no = ?', [accountNo]);
    if (!account.length) return errResp('Account ' + accountNo + ' not found', 404);
    const txns = runQuery('SELECT * FROM transactions WHERE from_account = ? OR to_account = ? ORDER BY timestamp DESC LIMIT 50', [accountNo, accountNo]);
    return ok({ accountNo, transactions: txns, total: txns.length, currentBalance: account[0].balance }, { latency: (Date.now() - t0) + 'ms' });
  },

  postLoanApply(params) {
    const t0 = Date.now();
    const { customerId, type = 'Personal', amount, tenureMonths = 36, interestRate } = params || {};
    logApi('/api/banking/loan/apply', 'POST', 'banking-usecases');
    if (!customerId || !amount) return errResp('customerId and amount required', 400);
    const customer = runQuery('SELECT * FROM customers WHERE customer_id = ?', [customerId]);
    if (!customer.length) return errResp('Customer ' + customerId + ' not found', 404);
    if (customer[0].kyc_status !== 'Verified') return errResp('KYC not verified. Loan cannot be disbursed.', 400);
    const rate = interestRate || randFloat(7, 14);
    const r = rate / 12 / 100;
    const emi = Math.round(amount * r * Math.pow(1 + r, tenureMonths) / (Math.pow(1 + r, tenureMonths) - 1));
    const loanId = 'LOAN' + uid();
    runExec("INSERT INTO loans (loan_id,customer_id,type,amount,tenure_months,interest_rate,emi,status,disbursed_at) VALUES (?,?,?,?,?,?,?,'Active',datetime('now'))",
      [loanId, customerId, type, amount, tenureMonths, rate, emi]);
    return ok({ loanId, customerId, type, amount, tenureMonths, interestRate: rate, emi, status: 'Active', message: 'Loan approved and disbursed' }, { latency: (Date.now() - t0) + 'ms' });
  },

  getLoans(customerId) {
    const t0 = Date.now();
    logApi('/api/banking/loans/' + customerId, 'GET', 'banking-usecases');
    const loans = runQuery('SELECT * FROM loans WHERE customer_id = ?', [customerId]);
    return ok({ customerId, loans, total: loans.length }, { latency: (Date.now() - t0) + 'ms' });
  },

  getBalance(accountNo) {
    const t0 = Date.now();
    logApi('/api/banking/balance/' + accountNo, 'GET', 'banking-usecases');
    const account = runQuery('SELECT account_no,customer_id,type,balance,currency,status FROM accounts WHERE account_no = ?', [accountNo]);
    if (!account.length) return errResp('Account ' + accountNo + ' not found', 404);
    return ok({ ...account[0], asOf: ts() }, { latency: (Date.now() - t0) + 'ms' });
  },

  postKycVerify(params) {
    const t0 = Date.now();
    const { customerId, panVerified = true, aadhaarVerified = true, faceMatch = true } = params || {};
    logApi('/api/banking/kyc/verify', 'POST', 'banking-usecases');
    if (!customerId) return errResp('customerId required', 400);
    const customer = runQuery('SELECT * FROM customers WHERE customer_id = ?', [customerId]);
    if (!customer.length) return errResp('Customer ' + customerId + ' not found', 404);
    const allPassed = panVerified && aadhaarVerified && faceMatch;
    const status = allPassed ? 'Verified' : 'Rejected';
    runExec('UPDATE customers SET kyc_status = ? WHERE customer_id = ?', [status, customerId]);
    runExec("INSERT INTO audit_log (entity_type,entity_id,action,new_value,performed_by) VALUES ('kyc',?,'KYC_UPDATE',?,?)",
      [customerId, JSON.stringify({ panVerified, aadhaarVerified, faceMatch, status }), 'api']);
    return ok({ customerId, status, panVerified, aadhaarVerified, faceMatch, message: 'KYC ' + status }, { latency: (Date.now() - t0) + 'ms' });
  },

  getCards(customerId) {
    const t0 = Date.now();
    logApi('/api/banking/cards/' + customerId, 'GET', 'banking-usecases');
    const customer = runQuery('SELECT * FROM customers WHERE customer_id = ?', [customerId]);
    if (!customer.length) return errResp('Customer ' + customerId + ' not found', 404);
    const accounts = runQuery('SELECT account_no, type FROM accounts WHERE customer_id = ?', [customerId]);
    const cards = accounts.map((acc, i) => ({
      cardId: 'CARD' + customerId + String(i + 1).padStart(3, '0'),
      accountNo: acc.account_no,
      cardType: acc.type === 'Current' ? 'Business Debit' : 'Debit',
      network: randItem(['Visa', 'Mastercard', 'RuPay']),
      maskedNumber: '**** **** **** ' + randInt(1000, 9999),
      expiryMonth: String(randInt(1, 12)).padStart(2, '0'),
      expiryYear: String(new Date().getFullYear() + randInt(1, 5)),
      status: 'Active',
      dailyLimit: 100000,
      internationalEnabled: false
    }));
    return ok({ customerId, cards, total: cards.length }, { latency: (Date.now() - t0) + 'ms' });
  },

  getAuditLog() {
    const t0 = Date.now();
    logApi('/api/banking/audit-log', 'GET', 'banking-usecases');
    const logs = runQuery('SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT 100');
    return ok({ auditLog: logs, total: logs.length }, { latency: (Date.now() - t0) + 'ms' });
  }
};

