// ═══════════════════════════════════════════════
//  EXPANDABLE CARD COMPONENT
// ═══════════════════════════════════════════════
function ExpandableCard({ item, accentColor, renderContent }) {
  const [expanded, setExpanded] = useState(false);

  return (
    <div
      style={{
        background: '#ffffff',
        borderRadius: 10,
        borderLeft: `5px solid ${accentColor}`,
        boxShadow: `0 2px 8px ${C.shadow}`,
        marginBottom: 12,
        overflow: 'hidden',
        transition: 'box-shadow 0.2s',
      }}
    >
      {/* Header (always visible) */}
      <div
        onClick={() => setExpanded(!expanded)}
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '14px 18px',
          cursor: 'pointer',
          background: expanded ? C.statBg : '#ffffff',
          transition: 'background 0.2s',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, flex: 1 }}>
          <span
            style={{
              background: accentColor,
              color: '#fff',
              fontWeight: 700,
              fontSize: 11,
              padding: '3px 8px',
              borderRadius: 4,
              letterSpacing: 0.5,
              whiteSpace: 'nowrap',
            }}
          >
            {item.id}
          </span>
          <span style={{ fontWeight: 600, color: '#212529', fontSize: 15 }}>
            {item.title || item.responsibility || item.tool}
          </span>
        </div>
        <span
          style={{
            fontSize: 18,
            color: C.muted,
            transform: expanded ? 'rotate(180deg)' : 'rotate(0deg)',
            transition: 'transform 0.2s',
            flexShrink: 0,
          }}
        >
          &#9660;
        </span>
      </div>

      {/* Expanded Content */}
      {expanded && (
        <div style={{ padding: '0 18px 16px', borderTop: `1px solid ${C.border}` }}>
          {renderContent(item)}
        </div>
      )}
    </div>
  );
}

