// ═══════════════════════════════════════════════
//  DETAIL FIELD COMPONENT
// ═══════════════════════════════════════════════
function DetailField({ label, value, color }) {
  if (!value) return null;
  return (
    <div style={{ marginTop: 10 }}>
      <span
        style={{
          fontSize: 11,
          fontWeight: 700,
          textTransform: 'uppercase',
          color: color || C.muted,
          letterSpacing: 0.8,
        }}
      >
        {label}
      </span>
      <div style={{ fontSize: 14, color: '#212529', marginTop: 3, lineHeight: 1.6 }}>
        {Array.isArray(value) ? (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 4 }}>
            {value.map((v, i) => (
              <span
                key={i}
                style={{
                  background: C.statBg,
                  color: '#212529',
                  padding: '3px 10px',
                  borderRadius: 6,
                  fontSize: 13,
                  border: `1px solid ${C.border}`,
                }}
              >
                {v}
              </span>
            ))}
          </div>
        ) : (
          value
        )}
      </div>
    </div>
  );
}

